import uuid
from typing import Optional
from sqlalchemy import String, DateTime, ForeignKey, Text, JSON
from sqlalchemy.dialects.postgresql import UUID
from sqlalchemy.orm import Mapped, mapped_column, relationship
from app.models.base import Base, UUIDMixin, TimestampMixin


class ClinicalNote(Base, UUIDMixin, TimestampMixin):
    """Structured clinical documentation generated by Gemini AI and reviewed by doctor."""
    __tablename__ = "clinical_notes"

    consultation_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        ForeignKey("consultations.id", ondelete="CASCADE"),
        unique=True,
        index=True,
        nullable=False,
    )
    
    # Raw transcript
    raw_transcript: Mapped[str] = mapped_column(Text, nullable=False)
    detected_language: Mapped[str] = mapped_column(String(64), default="Tamil / English (Tanglish)", nullable=False)

    # Structured extraction sections
    chief_complaint: Mapped[str] = mapped_column(String(512), nullable=False)
    history_of_present_illness: Mapped[str] = mapped_column(Text, nullable=False)
    symptoms: Mapped[list] = mapped_column(JSON, default=list, nullable=False)
    examination_findings: Mapped[Optional[str]] = mapped_column(Text, nullable=True)
    doctor_assessment_diagnosis: Mapped[str] = mapped_column(String(512), nullable=False)
    medication_instructions: Mapped[list] = mapped_column(JSON, default=list, nullable=False)
    advice: Mapped[list] = mapped_column(JSON, default=list, nullable=False)
    follow_up_instructions: Mapped[str] = mapped_column(String(512), nullable=False)

    # AI Safety & Traceability
    uncertain_information: Mapped[list] = mapped_column(JSON, default=list, nullable=False)
    missing_information: Mapped[list] = mapped_column(JSON, default=list, nullable=False)
    model_name: Mapped[str] = mapped_column(String(64), default="gemini-1.5-pro", nullable=False)
    prompt_version: Mapped[str] = mapped_column(String(64), default="v1.2.0-clinical-safety", nullable=False)

    # Doctor Approval & Audit Trail
    is_doctor_approved: Mapped[bool] = mapped_column(default=False, nullable=False)
    approved_by_doctor_id: Mapped[Optional[uuid.UUID]] = mapped_column(UUID(as_uuid=True), ForeignKey("users.id"), nullable=True)
    approved_at: Mapped[Optional[str]] = mapped_column(String(64), nullable=True)
    doctor_edits_applied: Mapped[bool] = mapped_column(default=False, nullable=False)

    # Relationship back to consultation
    consultation = relationship("Consultation", back_populates="clinical_note")

